'use strict';
const KEY='aerocare-teamwow-v1', $=s=>document.querySelector(s);
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHtml;
const iconPaths={brief:'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4',history:'M3 11a9 9 0 1 1 3 8 M3 4v7h7 M12 7v6l4 2',confirm:'M4 12l5 5L20 6',overview:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',profile:'M3 12h18 M14 5l7 7-7 7 M6 5l3 7-3 7',documents:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h7',readiness:'M9 5h11v16H4V5h3 M9 3h6v4H9z M8 12l2 2 5-4 M8 18h8',airline:'M4 21V7l8-4 8 4v14 M8 10h1 M15 10h1 M8 14h1 M15 14h1 M10 21v-4h4v4',demos:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',save:'M4 3h14l3 3v15H3V3z M7 3v6h10V3 M7 21v-8h10v8',check:'M4 12l5 5L20 6',back:'M19 12H5 M11 6l-6 6 6 6',next:'M5 12h14 M13 6l6 6-6 6',upload:'M12 16V3 M6 9l6-6 6 6 M4 15v6h16v-6'};
function icon(name){return `<svg class="ui-icon" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.check}"/></svg>`;}
function journeySteps(current){const steps=[['profile','Journey'],['documents','Documents'],['readiness','Preparation'],['confirm','Review & submit']];return `<nav class="journey-steps" aria-label="Travel preparation steps">${steps.map(([id,label],i)=>`<a href="#${id}" class="journey-step ${current===id?'is-current':''}" ${current===id?'aria-current="step"':''}>${icon(id)}<span><small>STEP 0${i+1}</small>${label}</span></a>`).join('')}</nav>`;}
function pageActions(current){if(current==='documents')return `<div class="page-actions">${btn(icon('back')+'Back to journey','profile','secondary')}<button class="btn" data-action="save-continue-documents">${icon('save')}Save & continue to preparation ${icon('next')}</button></div>`;if(current==='readiness')return `<div class="page-actions">${btn(icon('back')+'Back to documents','documents','secondary')}${btn(icon('check')+'Review & submit'+icon('next'),'confirm')}</div>`;if(current==='airline')return `<div class="page-actions">${btn(icon('back')+'Return to passenger view','readiness','secondary')}${btn(icon('overview')+'Overview','overview','secondary')}</div>`;return '';}

function fresh(){return {profile:null,completed:[],docs:{},submitted:false,review:'Not submitted',reviewNote:'',assistance:{},activity:[],documentsSavedAt:null,draft:null,draftAt:null,corrections:{},needsResubmit:false,submittedAt:null,changes:[]};}
let state=fresh(),storageAvailable=true,cases=[],activeId='',resetApplied=false;
function caseId(){return 'case-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);}
function cloneCase(value){return JSON.parse(JSON.stringify(value));}
function loadCases(saved){
 if(saved?.version===2&&Array.isArray(saved.cases)&&saved.cases.length){cases=saved.cases;activeId=cases.some(c=>c.id===saved.activeId)?saved.activeId:cases[0].id;state={...fresh(),...cloneCase(cases.find(c=>c.id===activeId).state)};}
 else if(saved?.state&&Array.isArray(saved.state.completed)){state={...fresh(),...saved.state};activeId=caseId();cases=[{id:activeId,state:cloneCase(state),updatedAt:new Date().toISOString()}];}
 else{activeId=caseId();state=fresh();cases=[];}
}
// One-time reset requested by the owner. New cases survive future refreshes.
const RESET_MARKER='aerocare-demo-reset-2026-11-12';
try{if(!localStorage.getItem(RESET_MARKER)){const hadCases=!!localStorage.getItem(KEY);localStorage.removeItem(KEY);localStorage.removeItem(KEY+'-legacy-backup');localStorage.setItem(RESET_MARKER,'done');resetApplied=hadCases;}loadCases(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{storageAvailable=false;activeId=caseId();}
function save(){try{const next=cases.filter(c=>c.id!==activeId);next.push({id:activeId,state:cloneCase(state),updatedAt:new Date().toISOString()});const previous=localStorage.getItem(KEY);if(previous&&!localStorage.getItem(KEY+'-legacy-backup')){const parsed=JSON.parse(previous);if(parsed.version===1)localStorage.setItem(KEY+'-legacy-backup',previous);}localStorage.setItem(KEY,JSON.stringify({version:2,activeId,cases:next}));cases=next;storageAvailable=true;return true;}catch{storageAvailable=false;toast('Browser storage is unavailable. Your previous saved demos have not been replaced.');return false;}}
function newDemo(){if(!save())return;const oldId=activeId,oldState=state;activeId=caseId();state=fresh();if(!save()){activeId=oldId;state=oldState;return;}location.hash='profile';render();toast('New blank demo started. Your previous demo is saved in My demos.');}
function openDemo(id){if(id===activeId){location.hash=state.profile?'overview':'profile';render();return;}if(!save())return;const item=cases.find(c=>c.id===id);if(!item)return;const oldId=activeId,oldState=state;activeId=id;state={...fresh(),...cloneCase(item.state)};if(!save()){activeId=oldId;state=oldState;return;}location.hash=state.profile?'overview':'profile';render();toast('Saved demo opened.');}
function demos(){const list=cases.slice().sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return heading('Your saved workspace','My demos','Start a fresh case here and keep your earlier demos in the same browser.','<button class="btn" data-action="new-demo">＋ New demo</button>')+`<div class="demo-cases">${list.length?list.map(c=>`<section class="panel"><div class="panel-title"><h2>${e(c.state.draft?.name||c.state.profile?.name||'New demo · name not entered')}</h2>${pill(c.id===activeId?'Current demo':'Saved demo',c.id===activeId?'blue':'')}</div><p class="tiny muted">${c.state.profile?e(c.state.profile.from+' → '+c.state.profile.to)+' · '+e(c.state.profile.flightNumber||c.state.profile.airline):'Blank form. Enter the passenger name to begin.'}</p><p class="tiny muted">${e(c.state.review||'Not submitted')} · ${Object.keys(c.state.docs||{}).length} document records</p><button class="btn secondary" data-open-case="${e(c.id)}">${c.id===activeId?'Continue this demo →':'Open saved demo →'}</button></section>`).join(''):empty('No saved demos yet','Start a new demo and enter your passenger’s details.')}</div><div class="notice">These demos are saved in this browser only. Clearing browser site data will remove them. No real passenger information should be entered.</div>`;}
function log(message){state.activity.unshift({message,at:new Date().toISOString()});state.activity=state.activity.slice(0,250);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const titles={demos:'My demos',overview:'Overview',profile:'Health & journey',readiness:'Your preparation plan',documents:'Documents',airline:'Demo airline review',guide:'How this demo works',confirm:'Review & submit',brief:'Travel brief',history:'Case history'};
const pill=(text,type='')=>`<span class="tag ${type}">${e(text)}</span>`;
const btn=(text,href,cls='')=>`<a class="btn ${cls}" href="#${href}">${text}</a>`;
function heading(kicker,title,sub,action=''){return `<div class="heading-row"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
function sourceLink(s){return s?`<a class="source" href="${s.url}" target="_blank" rel="noopener noreferrer">${e(s.name)} ↗</a>`:'';}
function assessment(){return AeroRules.assess(state.profile);}
function requirementReason(item){const owner=item.owner||(item.id==='medif'||item.id==='report'?'Treating clinician':'Passenger + treating clinician');return `<details class="requirement-reason"><summary>Why this item · who prepares it · what is checked</summary><p><strong>Why for this journey:</strong> ${e(item.why||'This item follows the needs recorded for this journey.')}</p><p><strong>Prepared with:</strong> ${e(owner)}</p><p><strong>AeroCare checks:</strong> ${item.id==='report'?'A recorded filename and the supported issue-date rule, where applicable.':'Checklist progress or recorded file metadata only.'} Medical content and airline acceptance require human review.</p>${sourceLink(item.source)}<p class="tiny muted">Stored example guidance checked ${e(AeroRules.checked)}. Requirements are not checked live with the airline.</p></details>`;}

function reviewState(){return assessment().medical?state.review:'No review trigger identified';}

function formatDate(s){if(!s)return 'Date not set';return new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});}
function counts(){if(!state.profile)return {all:0,done:0,missing:0};const a=assessment();return {all:a.tasks.length,done:a.tasks.filter(t=>state.completed.includes(t.id)).length,missing:docChecks().filter(d=>!d.ok).length};}
function activity(limit=8){return state.activity.length?`<ol class="case-timeline">${state.activity.slice(0,limit).map(a=>`<li><span class="timeline-dot" aria-hidden="true"></span><div><strong>${e(a.message)}</strong><time datetime="${e(a.at)}">${stamp(a.at)}</time></div></li>`).join('')}</ol>`:'<p class="muted">Updates will appear here as you prepare and share your case.</p>';}

function empty(title,description){return `<section class="panel empty"><div class="empty-symbol" aria-hidden="true">✳</div><h2>${title}</h2><p>${description}</p><div class="actions" style="justify-content:center">${btn('Create a travel case','profile')}</div></section>`;}
function ticket(){const p=state.profile;return `<div class="ticket"><div class="ticket-top"><span>YOUR NEXT JOURNEY</span><span aria-hidden="true">✈</span></div><div class="route"><div class="airport">${e(p?.from||'—')}<small>Departure</small></div><div class="flightpath" aria-hidden="true">···· ✈ ····</div><div class="airport">${e(p?.to||'—')}<small>Arrival</small></div></div><div class="ticket-bottom"><span>${p?formatDate(p.departure)+(p.departureTime?' · '+e(p.departureTime):''):'Your journey starts here'}</span><strong>${e(p?.flightNumber||p?.airline||'Plan ahead')}</strong></div></div>`;}
function overview(){const p=state.profile,c=counts(),a=p?assessment():null,items=attentionItems();return heading('Your travel preparation workspace',p?`Your journey, ${e(p.name.split(' ')[0])}.`:'Your journey, with care.','A little preparation, a little more peace of mind.',btn(icon('documents')+'Travel brief','brief','secondary'))+`<section class="flight-overview"><div><div class="eyebrow">BEFORE YOU TAKE OFF</div><h2>${p?'One journey. A clear next step.':'Make room for peace of mind.'}</h2><p>${p?'Your actions, medical review and assistance arrangements stay together, with a separate status for each.':'Add your journey and support needs. AeroCare will help organise the preparation, one step at a time.'}</p>${btn(icon('next')+(p?(items[0]?.action||'View preparation plan'):(state.draft?'Continue saved draft':'Prepare my journey')),p?(items[0]?.href||'readiness'):'profile')}</div>${ticket()}</section>${state.draft?'<div class="notice amber">You have saved journey edits that are not yet applied to this plan. '+btn('Continue editing','profile','secondary small')+'</div>':''}${p?`<div class="status-strip"><div><small>Your actions</small><strong>${c.done} of ${c.all} completed</strong></div><div><small>Document checks</small><strong>${c.missing?c.missing+' need attention':'No metadata checks outstanding'}</strong></div><div><small>Medical review · simulated</small><strong>${e(medicalLabel())}</strong></div><div><small>Assistance · simulated</small><strong>${supportSummary()}</strong></div></div>`:''}<div class="grid"><section class="panel attention"><div class="panel-title"><h2>What needs attention?</h2>${pill(items.length+' next steps','blue')}</div>${items.map(x=>`<a class="attention-item" href="#${x.href}"><div>${pill(x.owner,x.owner==='Your action'?'blue':'amber')}<h3>${e(x.title)}</h3><p>${e(x.detail)}</p></div>${icon('next')}</a>`).join('')||'<p>Your recorded actions are up to date. Keep an eye on your review and arrangements.</p>'}</section><section class="panel"><div class="panel-title"><h2>Latest case updates</h2>${btn('Full history','history','ghost small')}</div>${activity(4)}</section></div><div class="notice">Fictional-data prototype · no information is sent to an airline. Preparation progress is not medical clearance.</div>`;}

function profile(){const p=state.draft||state.profile||{},checked=id=>(p.supports||[]).includes(id)?'checked':'',selected=(key,v)=>p[key]===v?'selected':'';
 return heading('Step 01 · Health profile','Let’s prepare your journey.','Only relevant details. Fictional information for this prototype.','')+
 `<div id="draft-status" class="save-status" role="status">${state.draftAt?'Draft saved in this browser · '+stamp(state.draftAt):'Your progress will autosave in this browser as you type.'}</div><div class="grid"><form id="profile-form" class="panel"><div class="panel-title"><h2>Flight booking / boarding pass details</h2>${pill('FICTIONAL DATA')}</div><div class="form-grid">
 <div class="field"><label for="name">Passenger name *</label><input id="name" name="name" value="${e(p.name)}" placeholder="Enter passenger name" maxlength="80" required></div>
 <div class="field"><label for="airline">Operating airline *</label><select id="airline" name="airline" required><option value="">Select an airline</option><option ${selected('airline','Air India')}>Air India</option><option ${selected('airline','Emirates')}>Emirates</option></select><small>Two airlines with linked example guidance. Not an airline partnership.</small></div>
 <div class="field"><label for="flightNumber">Flight number *</label><input id="flightNumber" name="flightNumber" value="${e(p.flightNumber)}" placeholder="Enter flight number" pattern="[A-Za-z0-9 -]{2,12}" maxlength="12" required></div>
 <div class="field"><label for="pnr">Fictional booking reference / PNR *</label><input id="pnr" name="pnr" value="${e(p.pnr)}" placeholder="Enter booking reference" pattern="[A-Za-z0-9]{6}" maxlength="6" required><small>Use a fictional 6-character reference. No airline booking is retrieved or verified.</small></div>
 <div class="field"><label for="from">Departure airport code *</label><input id="from" name="from" value="${e(p.from)}" placeholder="Enter departure airport code" pattern="[A-Za-z]{3}" maxlength="3" required></div>
 <div class="field"><label for="to">Arrival airport code *</label><input id="to" name="to" value="${e(p.to)}" placeholder="Enter arrival airport code" pattern="[A-Za-z]{3}" maxlength="3" required></div>
 <div class="field"><label for="departure">Departure date *</label><input id="departure" name="departure" type="date" value="${e(p.departure)}" required></div>
 <div class="field"><label for="departureTime">Departure time *</label><input id="departureTime" name="departureTime" type="time" value="${e(p.departureTime)}" required><small>Local time at the departure airport.</small></div>
 <div class="field"><label for="seat">Seat number (optional)</label><input id="seat" name="seat" value="${e(p.seat)}" placeholder="Enter seat number" pattern="[A-Za-z0-9 -]{1,8}" maxlength="8"><small>Leave blank if a seat has not been assigned.</small></div>
 <div class="field"><label for="duration">Flight duration (hours) *</label><input id="duration" name="duration" type="number" min="0.25" max="24" step="0.25" value="${e(p.duration)}" placeholder="Enter duration in hours" required></div></div>
 <div class="form-section"><h2>Assistance you would like to arrange</h2><p class="tiny muted">Assistance requests are tracked separately from medical review. Selecting mobility assistance alone does not mean you need medical permission.</p><div class="checks">${[['wheelchair','Airport mobility assistance'],['oxygen','Clinician-prescribed oxygen'],['equipment','Medical equipment'],['stretcher','Stretcher / medical escort']].map(([id,l])=>`<label class="check"><input type="checkbox" name="supports" value="${id}" ${checked(id)}>${l}</label>`).join('')}</div></div>
 <div class="form-section"><h2>Relevant health information</h2><p class="tiny muted">These questions organise preparation. They do not diagnose illness.</p><div class="form-grid">
 <div class="field"><label for="condition">Main medical consideration *</label><select id="condition" name="condition" required><option value="">Select a consideration</option>${[['none','None reported'],['kidney','Kidney disease / dialysis'],['heart','Heart condition'],['lung','Lung condition'],['diabetes','Diabetes'],['other','Other medical consideration']].map(([v,l])=>`<option value="${v}" ${selected('condition',v)}>${l}</option>`).join('')}</select></div>
 <div class="field"><label for="stability">Current situation *</label><select id="stability" name="stability" required><option value="">Select an answer</option><option value="stable" ${selected('stability','stable')}>No recent worsening reported</option><option value="changed" ${selected('stability','changed')}>New or worsening symptoms</option><option value="unsure" ${selected('stability','unsure')}>I am not sure</option></select></div>
 <div class="field full"><label for="recent">Recent procedure or hospitalisation? *</label><select id="recent" name="recent" required><option value="">Select an answer</option><option value="no" ${selected('recent','no')}>No</option><option value="yes" ${selected('recent','yes')}>Yes — needs individual review</option></select></div>
 <div class="field full"><label for="medicines">Medicines relevant to the journey</label><textarea id="medicines" name="medicines" maxlength="600" placeholder="Use fictional details; do not change prescribed treatment here.">${e(p.medicines)}</textarea></div>
 <div class="field full"><label for="procedures">Condition, procedure or equipment notes</label><textarea id="procedures" name="procedures" maxlength="800" placeholder="Include relevant dates and assistance details for the demo.">${e(p.procedures)}</textarea></div></div></div>
 <div class="form-section"><h2>Your sharing choice</h2><label class="check consent"><input type="checkbox" name="consent" ${p.consent?'checked':''}><span>I allow this fictional case summary to appear in the demo airline view when I choose to share it.<br><small class="muted">No real airline receives information. You can withdraw this permission.</small></span></label></div>
 <div class="form-actions">${btn(icon('back')+'Back to overview','overview','secondary')}<span class="tiny muted">* Required fields</span><button class="btn" type="submit">${icon('save')}Save & continue to documents ${icon('next')}</button></div></form>
 <aside><section class="panel next-action"><div class="eyebrow">ONE ORGANISED TRAVEL CASE</div><h2>A plan that starts with you.</h2><p>Your answers help us show relevant example documents and support tasks.</p><div class="mini-row"><span>01 &nbsp; Add health & flight details</span></div><div class="mini-row"><span>02 &nbsp; Prepare documents</span></div><div class="mini-row"><span>03 &nbsp; Review your preparation plan</span></div></section><section class="panel"><h3>Feeling seriously unwell?</h3><p class="tiny muted">For severe symptoms such as chest pain, severe breathing difficulty or loss of consciousness, seek emergency medical help immediately. Do not wait for this checklist.</p><h3>What gets saved?</h3><p class="tiny muted">Fictional profile information and demo status stay in this browser. This prototype is not suitable for real medical records.</p></section></aside></div>`;
}
function checklistSubmit(){return `<div class="checklist-submit"><h3>${state.submitted&&!state.needsResubmit?'Your case has been shared':'Review your case before sharing'}</h3><p>Check the details, outstanding items and sharing permission on one final screen.</p>${state.submitted?`<p class="tiny">${e(state.review)} · ${state.submittedAt?stamp(state.submittedAt):'Previously submitted'}${state.needsResubmit?' · Changes are waiting for resubmission.':''}</p>`:''}<div class="actions">${btn(icon('check')+(state.submitted&&!state.needsResubmit?'View submitted summary':'Review & '+(state.submittedAt?'resubmit case':'submit case')),'confirm')}${state.submitted?btn('Open demo reviewer view','airline','secondary'):''}</div></div>`;}

function readiness(){if(!state.profile)return empty('Start with your journey','Enter fictional details to build a preparation plan.');const a=assessment(),c=counts();return heading('Step 03 · Your actions','A clear plan for your journey.','Tick the actions you have taken. Clinician and reviewer responsibilities remain visible.',btn('Review travel brief','brief','secondary'))+`${a.changed?'<div class="notice amber">Your reported health change or uncertainty needs individual assessment by your treating team and the operating airline. AeroCare cannot decide whether you are fit to travel.</div>':''}<div class="grid"><section class="panel"><div class="panel-title"><h2>Preparation checklist</h2>${pill(c.done+' of '+c.all+' completed','blue')}</div><div class="progress"><span style="width:${c.all?c.done/c.all*100:0}%"></span></div><p class="tiny muted">Checked means passenger-reported progress. It does not confirm clinician assessment, document acceptance or service availability.</p>${a.tasks.map(t=>`<div class="checklist-item" id="preparation-${t.id}"><input id="task-${t.id}" type="checkbox" data-task="${t.id}" ${state.completed.includes(t.id)?'checked':''}><div><label for="task-${t.id}"><strong>${e(t.title)}</strong></label><p>${e(t.detail)}</p>${pill(taskOwner(t),taskOwner(t)==='Your action'?'blue':'amber')} <span class="tiny muted">${e(t.owner)}</span>${requirementReason(t)}</div></div>`).join('')}${checklistSubmit()}</section><aside><section class="panel"><h2>Medical review</h2><p>${e(medicalLabel())}</p><p class="tiny muted">${a.medical||a.individual?'A clinician and airline reviewer must assess the medical requirements.':'No medical-review trigger is identified by this limited rule set. This does not establish fitness to fly.'}</p>${state.reviewNote?`<div class="notice amber">${e(state.reviewNote)}</div>`:''}</section><section class="panel"><h2>Assistance arrangements</h2><p class="tiny muted">Confirmed separately from medical review.</p>${supportRows(false)}</section><section class="panel"><h2>Who does what?</h2><p class="tiny">${pill('Your action','blue')} Add details, record documents and report preparations.</p><p class="tiny">${pill('Treating clinician','amber')} Prepare medical information and advise on individual care.</p><p class="tiny">${pill('Awaiting reviewer','amber')} Resolve requirements and confirm arrangements in this simulated workflow.</p></section></aside></div>`;}
const supportNames={wheelchair:'Airport mobility assistance',oxygen:'Prescribed oxygen',equipment:'Medical equipment',stretcher:'Stretcher / escort'};

function supportRows(edit){const supports=state.profile.supports||[];return supports.length?supports.map(id=>`<div class="support-row"><div class="mini-row"><strong>${supportNames[id]}</strong>${pill(state.assistance[id]||'Not yet shared',state.assistance[id]==='Confirmed'?'blue':'amber')}</div>${edit?`<div class="status-actions" role="group" aria-label="${supportNames[id]} actions">${[['Requested','Mark requested'],['Information needed','Request information'],['Confirmed','Confirm assistance'],['Unavailable','Mark unavailable']].map(([value,label])=>`<button type="button" class="btn small ${(state.assistance[id]||'Requested')===value?'':'secondary'}" data-support-action="${id}" data-status="${value}" aria-pressed="${(state.assistance[id]||'Requested')===value}">${value==='Confirmed'?icon('check'):''}${label}</button>`).join('')}</div>`:''}</div>`).join(''):'<p class="tiny muted">No additional assistance requested.</p>';}
function documentReceipt(d){const record=state.docs[d.id];if(!record)return '';return `<div class="document-receipt ${storageAvailable?'':'unsaved'}" role="status"><strong>${storageAvailable?'✓ Document successfully added to your demo case':'Document selected · not saved in browser'}</strong><span>${e(record.name)}</span><small>${storageAvailable?'Saved in this browser':'Browser storage is unavailable'} · ${new Date(record.at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small><small>${record.blobKey?'File saved locally for same-browser preview.':'Older record: reattach the fictional file to enable preview.'} Content not medically verified.</small></div>`;}
function documentSavePanel(){const checks=docChecks(),recorded=checks.filter(d=>state.docs[d.id]).length,outstanding=checks.filter(d=>!d.ok).length;return `<div class="documents-save-panel"><div><h3>Save your document progress</h3><p class="tiny muted">${recorded} of ${checks.length} document records added.${outstanding?' '+outstanding+' preparation check'+(outstanding===1?'':'s')+(outstanding===1?' still needs attention.':' still need attention.'):''} Saving does not submit your case to an airline.</p>${state.documentsSavedAt&&storageAvailable?`<div class="document-save-success" role="status"><strong>✓ Documents saved successfully</strong><br><span>Saved in this browser at ${new Date(state.documentsSavedAt).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}. ${outstanding?'Outstanding items remain in your plan.':'Your recorded document progress is saved.'}</span></div>`:'<p class="tiny muted">Records save automatically as you add them. Use Save documents to confirm this step.</p>'}</div><div class="actions"><button class="btn" data-action="save-documents">${icon('save')}Save documents</button>${btn('Continue to preparation plan →','readiness','secondary')}</div></div>`;}
function documents(){if(!state.profile)return empty('Organise your documents','Save your journey first.');const a=assessment(),checks=docChecks();return heading('Step 02 · Document preparation','The details, together.','Record fictional files, see exactly what is missing, and respond to specific reviewer requests.')+`<div class="grid"><section class="panel"><h2>Documents for this journey</h2><p class="tiny muted">Fictional files are saved in this browser for preview. Nothing is sent to an airline. Content is not medically verified.</p>${checks.map(d=>{const r=state.corrections[d.id];return `<article class="doc-row" id="document-${d.id}"><div class="doc-top"><h3>${e(d.title)}</h3>${pill(d.status,d.ok?'blue':'amber')}</div><p>${e(d.detail)}</p>${requirementReason(d)}${r?`<div class="notice amber"><strong>Reviewer correction request</strong><p>${e(r.note)}</p><small>${stamp(r.at)} · ${e(r.status==='requested'?'Your action: replace this document':r.status==='responded'?'Replacement recorded · resubmit the case':'Replacement submitted · awaiting reviewer')}</small></div>`:''}<p class="tiny"><strong>Preparation check:</strong> ${e(d.checkDetail)}</p>${d.id==='report'&&state.profile.airline==='Air India'?`<div class="field"><label for="report-issued">Fictional report issue date</label><input id="report-issued" type="date" data-issued="report" value="${e(state.docs.report?.issuedDate||'')}" ${state.docs.report?'':'disabled'}><small>Date check only, not clinical acceptance.</small></div>`:''}${documentReceipt(d)}${documentPreviewButton(d.id)}<div class="actions"><label class="btn secondary" for="file-${d.id}">${icon('upload')}${state.docs[d.id]?'Replace fictional file':'Add fictional file'}</label><input id="file-${d.id}" type="file" data-doc="${d.id}" accept=".pdf,.png,.jpg,.jpeg,.txt" aria-label="Fictional file for ${e(d.title)}">${state.docs[d.id]?`<button class="btn ghost small" data-remove-doc="${d.id}">Remove record</button>`:''}</div></article>`;}).join('')||'<div class="notice">No additional document records identified by the supported examples. Any individual-review flag still requires human assessment.</div>'}${retainedDocuments()}${documentSavePanel()}${state.needsResubmit?checklistSubmit():''}</section><aside><section class="panel"><h2>Your document workflow</h2><ol class="plain-steps"><li>Record the required fictional file.</li><li>Review the metadata and any supported date check.</li><li>Save progress, then review and submit the case.</li><li>If a reviewer requests a correction, replace that specific file and resubmit.</li></ol><p class="tiny muted">Adding or replacing a file never silently completes a review.</p></section><section class="panel"><h2>Latest updates</h2>${activity(4)}</section></aside></div>`;}

function airline(){if(!state.profile||!state.profile.consent||!state.submitted)return heading('Simulated reviewer workspace','Demo airline review','A consented case appears here only after explicit submission.')+empty('No shared case','Save and review your journey, give sharing permission and submit the fictional case.');const p=state.profile,a=assessment();return heading('Simulated reviewer workspace','Coordinate the next step.','Manual demonstration controls. No real airline or clinical approval.',pill(state.needsResubmit?'PASSENGER UPDATES PENDING':'SHARED WITH CONSENT','blue'))+`<div class="notice amber">All statuses on this page are simulated. Locally saved fictional documents can be previewed below. These controls do not issue boarding permission or medical clearance.</div>${state.needsResubmit?'<div class="notice amber">The passenger is updating this case. Wait for explicit resubmission before completing review or confirming arrangements.</div>':''}<div class="grid"><div><section class="panel"><div class="panel-title"><h2>${e(p.name)}</h2>${btn('Travel brief','brief','secondary small')}</div>${journeyDetails()}<h3 style="margin-top:24px">Passenger-reported health information</h3>${healthDetails()}<p class="tiny"><strong>Latest changes:</strong> ${e((state.changes||[]).join(', ')||'No journey changes since first save.')}</p></section><section class="panel"><h2>Document-specific review</h2>${docChecks().map(d=>`<article class="doc-row"><div class="doc-top"><h3>${e(d.title)}</h3>${pill(d.status,d.ok?'blue':'amber')}</div><p>${state.docs[d.id]?e(state.docs[d.id].name):'No file recorded'}</p>${documentPreviewButton(d.id)}<p class="tiny">${e(d.checkDetail)}</p>${state.corrections[d.id]?`<div class="notice amber">${e(state.corrections[d.id].note)}<br><small>${e(correctionLabel(state.corrections[d.id].status))}</small></div>`:''}<form class="correction-form" data-correction="${d.id}"><div class="field"><label for="correction-${d.id}">What needs correcting?</label><textarea id="correction-${d.id}" name="note" maxlength="600" required placeholder="Describe the specific missing or incorrect information."></textarea></div><button class="btn secondary small" type="submit">Request correction for this document</button></form></article>`).join('')||'<p class="muted">No document records identified by the supported examples.</p>'}</section><section class="panel"><h2>Assistance coordination</h2>${supportRows(true)}</section></div><aside><form id="review-form" class="panel"><div class="panel-title"><h2>${a.medical||a.individual?'Medical review':'Case coordination'}</h2>${pill('SIMULATED')}</div><p>${e(state.review)}</p><div class="field"><label for="reviewNote">Reviewer note</label><textarea id="reviewNote" name="reviewNote" maxlength="600" placeholder="Explain the next step or unresolved question.">${e(state.reviewNote)}</textarea></div><p class="tiny muted">${a.medical||a.individual?'Completing this review records a simulated workflow outcome only.':'This case has no medical-review trigger in the limited rules. Assistance confirmation remains separate.'}</p><div class="review-actions">${[['Review completed','Confirm demo review'],['Information requested','Request information'],['Pending review','Mark pending'],['Travel deferred','Mark travel deferred']].map(([v,l])=>`<button class="btn ${v==='Review completed'?'':'secondary'}" type="submit" value="${v}">${icon(v==='Review completed'?'check':'documents')}${l}</button>`).join('')}</div></form><section class="panel"><h2>Case history</h2>${activity(6)}${btn('Open full history','history','secondary small')}</section></aside></div>`;}

function guide(){return heading('The prototype, explained','Built for preparation.','A small, explainable demonstration of the architecture in our submitted presentation.')+
 `<div class="grid"><div><section class="panel"><h2>Try the complete journey</h2><p class="tiny muted">Start a blank case, enter fictional health and flight details, select fictional document files, then continue to your preparation plan and share with the demo airline. Switch to the reviewer view, add a note and update service statuses. Return to the passenger view to see the result.</p><div class="actions"><button class="btn danger" data-action="reset">Clear current demo</button></div></section><section class="panel"><h2>What each part does</h2>${[['HTML','Defines forms, headings, buttons and both connected views.'],['CSS','Controls layout, colours, mobile screens and printing.'],['JavaScript','Builds example checklists and handles user interactions.'],['Browser storage','Saves this fictional case on this browser and origin. Other devices cannot see it.'],['Example rules','Link preparation tasks to a small set of airline source pages. They are incomplete and do not determine fitness to fly.'],['Demo airline page','Shows a consented case and lets a team member simulate review and assistance updates.']].map(([k,v])=>`<div class="source-card"><h3>${k}</h3><p>${v}</p></div>`).join('')}</section></div><aside><section class="panel"><h2>Source notes</h2><p class="tiny muted">Example guidance checked 5 November 2026. AeroCare uses stored example guidance, not a live airline connection. Rules outside the supported examples need individual review.</p>${Object.values(AeroRules.sources).map(s=>`<div class="source-card">${sourceLink(s)}</div>`).join('')}<p class="tiny muted">The kidney-care planning item is a prompt to consult the treating team, not a clinical treatment recommendation.</p></section><section class="panel"><h2>Clear prototype boundaries</h2><p class="tiny muted">No medical diagnosis, automatic clearance, server uploads, airline notification or secure accounts. Consent controls the interface, not a production access-control system. Use fictional data only.</p><p class="tiny muted">AI assistance is disclosed in the project README. Team members should review the implementation and be able to explain the workflow.</p></section></aside></div>`;}
function render(){const page=location.hash.slice(1).split('/')[0]||'overview';closeDocumentPreview();const current=titles[page]?page:'overview';$('#crumb-title').textContent=titles[current];document.title=titles[current]+' · AeroCare';document.querySelectorAll('[data-page]').forEach(x=>{const on=x.dataset.page===current;x.classList.toggle('active',on);if(on)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current');});$('#main').innerHTML=(['profile','documents','readiness','confirm'].includes(current)?journeySteps(current):'')+({overview,profile,readiness,documents,airline,guide,demos,confirm:confirmPage,brief,history:historyPage}[current])()+pageActions(current);document.querySelectorAll('.sidebar nav [data-page]').forEach(link=>{const old=link.querySelector('span');if(old)old.outerHTML=icon(link.dataset.page);});const switcher=$('.review-switch');switcher.href=current==='airline'?'#readiness':'#airline';switcher.innerHTML=icon(current==='airline'?'back':'airline')+(current==='airline'?'Return to passenger view':'Switch to airline demo');if(['overview','readiness','documents'].includes(current)&&state.needsResubmit)$('#main').insertAdjacentHTML('afterbegin','<div class="notice amber">Your case needs an update. Resolve outstanding requests, then review and resubmit.</div>');const anchor=location.hash.slice(1).split('/')[1];if(anchor)requestAnimationFrame(()=>document.getElementById(anchor)?.scrollIntoView({block:'center'}));if(!storageAvailable)$('#main').insertAdjacentHTML('afterbegin','<div class="notice amber">Browser storage is unavailable. Changes may be lost on refresh.</div>');}
function printSummary(){if(!state.profile){toast('Save a journey first.');return;}$('#print-area').innerHTML=briefContent(true);window.print();}

function retainedDocuments(){const ids=assessment().docs.map(d=>d.id),records=Object.entries(state.docs).filter(([id])=>!ids.includes(id));return records.length?`<details class="requirement-reason"><summary>${records.length} retained record(s) outside the current plan</summary><p>Kept from earlier journey details. These records do not satisfy current requirements automatically.</p>${records.map(([id,r])=>`<p><strong>${e(id)}</strong> · ${e(r.name)} · ${stamp(r.at)}</p>`).join('')}</details>`:'';}
function stamp(at){return new Date(at).toLocaleString('en-IN',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});}
function taskOwner(t){return t.owner==='Medical reviewer'?'Awaiting reviewer':t.owner==='Treating clinician'?'Treating clinician':/clinician|care team/.test(t.owner)?'Your action + clinician':'Your action';}
function medicalLabel(){const a=assessment();return a.medical||a.individual?(state.needsResubmit?'Updated case needs resubmission':state.review):'No medical-review trigger identified';}
function supportSummary(){const ids=state.profile.supports||[];if(!ids.length)return 'None requested';return ids.filter(id=>state.assistance[id]==='Confirmed').length+' of '+ids.length+' confirmed';}
function activeCorrections(){const ids=assessment().docs.map(d=>d.id);return Object.entries(state.corrections).filter(([id])=>ids.includes(id)).map(([,r])=>r);}
function correctionLabel(status){return {requested:'Correction requested · replacement needed',responded:'Replacement recorded · passenger must resubmit',resubmitted:'Replacement resubmitted · awaiting reviewer',resolved:'Resolved in simulated review'}[status]||status;}
function docChecks(){return AeroRules.checkDocuments(state.profile,state.docs).map(d=>{const r=state.corrections[d.id];if(r?.status==='requested')return {...d,ok:false,status:'Correction requested',checkDetail:'Replace the recorded document to answer the reviewer’s specific request.'};if(r?.status==='responded'&&d.ok)return {...d,status:'Replacement recorded · resubmit'};return d;});}
function attentionItems(){if(!state.profile)return [{title:state.draft?'Finish your saved journey draft':'Start with your journey',detail:'Add the passenger, flight and assistance needs to create a relevant plan.',href:'profile',owner:'Your action',action:state.draft?'Continue draft':'Start my journey'}];const items=[];if(state.draft)items.push({title:'Finish your saved journey edits',detail:'Draft edits have not been applied to the preparation plan.',href:'profile',owner:'Your action',action:'Continue saved edits'});for(const d of docChecks()){if(!d.ok)items.push({title:d.title,detail:state.corrections[d.id]?.status==='requested'?state.corrections[d.id].note:d.checkDetail,href:'documents/document-'+d.id,owner:'Your action',action:'Review document requirements'});}if(state.review==='Information requested'&&state.reviewNote)items.push({title:'Reply to your reviewer’s request',detail:state.reviewNote,href:'confirm',owner:'Your action',action:'Review requested information'});if(state.needsResubmit)items.push({title:'Resubmit the updated case',detail:'Your saved changes require explicit resubmission before review continues.',href:'confirm',owner:'Your action',action:'Review & resubmit'});const next=assessment().tasks.find(t=>!state.completed.includes(t.id));if(next)items.push({title:next.title,detail:next.detail,href:'readiness/preparation-'+next.id,owner:taskOwner(next),action:'Open next preparation action'});if(!state.submitted)items.push({title:'Review your case before sharing',detail:'Check the summary, outstanding items and permission on the final screen.',href:'confirm',owner:'Your action',action:'Review case'});else if(!state.needsResubmit&&state.review==='Pending review')items.push({title:'Your case is awaiting a reviewer',detail:'Submission has been recorded in the simulated workflow.',href:'readiness',owner:'Awaiting reviewer',action:'View case status'});for(const id of state.profile.supports||[])if(state.assistance[id]!=='Confirmed')items.push({title:supportNames[id],detail:'Simulated arrangement status: '+(state.assistance[id]||'Not yet requested'),href:'readiness',owner:['Information needed','Unavailable'].includes(state.assistance[id])?'Your action':'Awaiting reviewer',action:'View assistance arrangements'});return items;}
const labels={name:'Passenger name',airline:'Operating airline',flightNumber:'Flight number',pnr:'Booking reference',from:'Departure airport',to:'Arrival airport',departure:'Departure date',departureTime:'Departure time',seat:'Seat',duration:'Flight duration',condition:'Medical consideration',stability:'Current situation',recent:'Recent procedure / hospitalisation',medicines:'Medicine notes',procedures:'Relevant notes',supports:'Assistance requests',consent:'Sharing permission'};
const conditionNames={none:'None reported',kidney:'Kidney disease / dialysis',heart:'Heart condition',lung:'Lung condition',diabetes:'Diabetes',other:'Other medical consideration'};
function detailRows(rows){return `<dl class="detail-list">${rows.map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v||'Not recorded')}</dd></div>`).join('')}</dl>`;}
function journeyDetails(){const p=state.profile;return detailRows([['Passenger',p.name],['Journey',p.from+' → '+p.to],['Operating airline',p.airline],['Flight',p.flightNumber],['Departure',formatDate(p.departure)+' · '+p.departureTime+' (departure airport local time)'],['Fictional booking reference',p.pnr],['Seat',p.seat||'Not assigned'],['Duration',p.duration+' hours']]);}
function healthDetails(){const p=state.profile;return detailRows([['Medical consideration',conditionNames[p.condition]],['Reported situation',{stable:'No recent worsening reported',changed:'New or worsening symptoms',unsure:'Unsure'}[p.stability]],['Recent procedure / hospitalisation',p.recent==='yes'?'Yes — individual review needed':'None reported'],['Medicine notes',p.medicines||'None recorded'],['Relevant notes',p.procedures||'None recorded']]);}
function confirmPage(){if(!state.profile)return empty('Save your journey first','Complete the journey details before reviewing a submission.');const p=state.profile,a=assessment(),out=docChecks().filter(x=>!x.ok),requests=activeCorrections().filter(x=>x.status==='requested'),already=state.submitted&&!state.needsResubmit,isResubmit=!!(state.submittedAt||state.submitted);return heading('Final check · Review before sharing','Everything in one place.','Review the case you are sharing in this fictional demonstration.')+`${state.draft?'<div class="notice amber">A saved journey draft is not applied. Finish those edits before submitting. '+btn('Finish edits','profile','secondary small')+'</div>':''}<div class="grid"><div><section class="panel"><div class="panel-title"><h2>Passenger & flight</h2>${btn('Edit journey','profile','secondary small')}</div>${journeyDetails()}</section><section class="panel"><div class="panel-title"><h2>Passenger-reported health & assistance</h2>${btn('Edit needs','profile','secondary small')}</div>${healthDetails()}<p><strong>Requested assistance:</strong> ${e((p.supports||[]).map(id=>supportNames[id]).join(', ')||'None requested')}</p><p class="tiny muted">These details are passenger-reported, not clinically verified.</p></section><section class="panel"><div class="panel-title"><h2>Document records</h2>${btn('Edit documents','documents','secondary small')}</div>${docChecks().map(d=>`<div class="mini-row"><div><strong>${e(d.title)}</strong><p class="tiny muted">${e(state.docs[d.id]?.name||'No file recorded')}</p></div>${pill(d.status,d.ok?'blue':'amber')}</div>`).join('')||'<p>No additional document records identified by the limited rules.</p>'}</section></div><aside><section class="panel submission-card"><h2>${already?'Submitted summary':'Ready to share?'}</h2><p class="tiny">${counts().done} of ${counts().all} actions marked complete. ${out.length} document check(s) need attention.</p>${a.individual?'<div class="notice amber">Individual requirements remain for a human reviewer to resolve.</div>':''}${out.length?'<p class="tiny muted">Missing records remain visible. You may submit an initial incomplete case for information review; this does not mark the plan complete.</p>':''}${requests.length?'<div class="notice amber">Replace each document with an open correction request before resubmitting.</div>':''}<div class="mini-row"><strong>Sharing permission</strong>${pill(p.consent?'Enabled':'Not enabled',p.consent?'blue':'amber')}</div><p class="tiny muted">Only this fictional case appears in the demo reviewer workspace. No airline receives it. ${!p.consent?'Enable the permission in your journey before submitting.':'You can withdraw sharing below.'}</p>${btn('Edit sharing choice','profile','ghost small')}<button class="btn full" data-action="submit" ${!p.consent||already||requests.length||state.draft?'disabled':''}>${icon('save')}${already?'Case submitted':isResubmit?'Resubmit for review':'Submit case for demo review'}</button>${already?'<div class="document-save-success">✓ Case submitted successfully<br>'+e(state.review)+'</div>':''}${state.submitted?'<button class="btn ghost" data-action="withdraw">Withdraw sharing permission</button>':''}<p class="tiny muted">Browser-local demonstration. Submission is not medical clearance or confirmation of assistance.</p></section>${btn('Back to preparation checklist','readiness','secondary')}</aside></div>`;}
function briefContent(print=false){const p=state.profile,a=assessment(),unresolved=attentionItems();return `<div class="brief-document"><div class="brief-masthead"><span>AeroCare.</span>${pill('FICTIONAL TRAVEL BRIEF','blue')}</div><h2>Travel preparation brief</h2><p class="tiny muted">Generated ${stamp(new Date().toISOString())} · Passenger-reported information · Not medical clearance</p><section><h3>Journey</h3>${journeyDetails()}</section><section><h3>Passenger-reported health information</h3>${healthDetails()}</section><section><h3>Requested assistance & simulated arrangements</h3>${supportRows(false)}</section><section><h3>Document metadata · file contents unchecked</h3>${docChecks().map(d=>`<p><strong>${e(d.title)}</strong><br>${e(state.docs[d.id]?.name||'No file recorded')}${state.docs[d.id]?.issuedDate?' · Issue date '+formatDate(state.docs[d.id].issuedDate):''}<br>${e(d.status)}. ${e(d.checkDetail)}</p>`).join('')||'<p>No additional records identified by the limited rules.</p>'}</section><section><h3>Unresolved actions & questions</h3>${unresolved.length?'<ul>'+unresolved.map(x=>`<li><strong>${e(x.owner)}:</strong> ${e(x.title)} — ${e(x.detail)}</li>`).join('')+'</ul>':'<p>No outstanding actions recorded by the limited rule set.</p>'}</section><section><h3>Simulated review</h3><p>${e(medicalLabel())}. Case status: ${e(state.review)}.</p>${state.reviewNote?'<p>Reviewer note: '+e(state.reviewNote)+'</p>':''}<p>Sharing: ${state.submitted&&p.consent?'Shared with the demo reviewer':'Not shared'}. No information has been sent to an airline.</p></section><section><h3>Preparation progress · passenger reported</h3><ul>${a.tasks.map(t=>`<li>${state.completed.includes(t.id)?'Complete':'To do'} — ${e(t.title)}</li>`).join('')}</ul></section><section><h3>Source & limitations</h3><p>Stored example guidance checked ${e(AeroRules.checked)}. ${sourceLink(a.source)}</p><p class="tiny muted">The clinician and operating airline determine medical requirements and travel acceptance. AeroCare records preparation only. Document authenticity, medical content and airline booking details are not verified.</p></section></div>`;}
function brief(){if(!state.profile)return empty('Your brief starts with your journey','Save a fictional journey to preview its travel brief.');return heading('Review, then print','Your travel brief.','Check the details below before printing or saving as PDF.',`<button class="btn" data-action="print">${icon('documents')}Print / save as PDF</button>`)+briefContent();}
function historyPage(){return heading('An understandable case record','Your case history.','Submissions, changes, correction requests and arrangement updates, with timestamps.')+`<section class="panel"><p class="tiny muted">Newest first · ${state.activity.length} recorded events in this browser.</p>${activity(state.activity.length)}</section>`;}
function readProfile(form){const f=new FormData(form),p=Object.fromEntries(f.entries());p.supports=f.getAll('supports');p.consent=f.has('consent');for(const k of ['name','from','to','flightNumber','pnr','seat'])p[k]=String(p[k]||'').trim();for(const k of ['from','to','flightNumber','pnr','seat'])p[k]=p[k].toUpperCase();return p;}
function autosaveDraft(){const form=$('#profile-form');if(!form)return;state.draft=readProfile(form);state.draftAt=new Date().toISOString();const ok=save(),node=$('#draft-status');if(node)node.textContent=ok?'✓ Draft saved in this browser · '+stamp(state.draftAt):'Draft could not be saved. Keep this page open.';}
function changedKeys(old,p){return old?Object.keys(labels).filter(k=>JSON.stringify(old[k])!==JSON.stringify(p[k])):[];}
function applyProfile(p){const old=state.profile,changes=changedKeys(old,p);state.profile=p;state.draft=null;state.draftAt=null;if(changes.length){state.changes=changes.map(k=>labels[k]);const affected=new Set();if(changes.some(k=>['airline','condition','stability','recent','procedures'].includes(k)))['review','procedure','individual','kidney','equipment','escort'].forEach(x=>affected.add(x));if(changes.includes('medicines'))affected.add('medicines');if(changes.some(k=>['departure','departureTime','duration','from','to'].includes(k)))['deadline','kidney','medicines'].forEach(x=>affected.add(x));if(changes.includes('supports'))['equipment','wheelchair','escort','review'].forEach(x=>affected.add(x));state.completed=state.completed.filter(id=>!affected.has(id)&&assessment().tasks.some(t=>t.id===id));if(changes.includes('airline')){for(const id of ['medif','report']){state.docs[id]&&(state.docs[id].needsRecheck=true);if(state.docs[id])state.corrections[id]={note:'Operating airline changed. Record the applicable airline form or current report for the updated journey.',at:new Date().toISOString(),status:'requested'};}}const operational=changes.some(k=>['airline','flightNumber','from','to','departure','departureTime','supports','procedures'].includes(k));for(const id of Object.keys(state.assistance)){if(!p.supports.includes(id))delete state.assistance[id];else if(operational)state.assistance[id]='Needs reconfirmation';}if(state.submitted){state.needsResubmit=true;state.review='Updates awaiting resubmission';}if(!p.consent){state.submitted=false;state.needsResubmit=false;state.review='Not submitted';state.assistance={};}log('Journey updated: '+state.changes.join(', ')+'. Relevant checks refreshed; document records retained.');}else log(old?'Journey confirmed without changes.':'Journey saved; preparation plan created.');return changes;}
function markCaseChanged(message){if(state.submitted){state.needsResubmit=true;state.review='Updates awaiting resubmission';}log(message);}
function transact(fn){const before=cloneCase(state);fn();if(!save()){state=before;render();return false;}return true;}
// Browser-local draft capture never applies unfinished changes to the plan.
document.addEventListener('input',event=>{if(event.target.closest('#profile-form'))autosaveDraft();});
document.addEventListener('submit',event=>{const form=event.target;
 if(form.id==='profile-form'){event.preventDefault();const p=readProfile(form);if(!p.name||p.from===p.to){toast('Enter a name and different departure and arrival airports.');return;}const end=new Date(p.departure+'T23:59:59');if(!Number.isFinite(end.getTime())||end<new Date()){toast('Choose today or a future departure date.');return;}if(!transact(()=>applyProfile(p)))return;location.hash='documents';render();toast('Journey saved. Existing document records have been kept.');}
 else if(form.dataset.correction){event.preventDefault();if(!state.submitted||!state.profile?.consent)return;const id=form.dataset.correction,note=String(new FormData(form).get('note')||'').trim();if(!note){toast('Describe what needs correcting.');return;}if(!transact(()=>{state.corrections[id]={note,at:new Date().toISOString(),status:'requested'};state.review='Information requested';state.needsResubmit=true;log('Demo reviewer requested correction: '+(assessment().docs.find(d=>d.id===id)?.title||id)+' — '+note);}))return;render();toast('Document correction request is visible to the passenger.');}
 else if(form.id==='review-form'){event.preventDefault();if(!state.submitted||!state.profile?.consent)return;const f=new FormData(form),status=event.submitter?.value,note=String(f.get('reviewNote')||'').trim();if(!status)return;if(status==='Review completed'&&(state.needsResubmit||docChecks().some(d=>!d.ok)||activeCorrections().some(r=>['requested','responded'].includes(r.status)))){toast('Wait for resubmission and resolve outstanding document checks before completing review.');return;}if(status==='Information requested'&&!note){toast('Add a note explaining the information needed.');return;}if(!transact(()=>{state.review=status;state.reviewNote=note;if(status==='Information requested')state.needsResubmit=true;if(status==='Review completed')for(const r of Object.values(state.corrections))r.status='resolved';log('Demo reviewer: '+status+(note?' — '+note:''));}))return;render();toast('Simulated review updated.');}
});
document.addEventListener('change',async event=>{const el=event.target;if(el.closest('#profile-form')){autosaveDraft();return;}if(el.dataset.task){transact(()=>{state.completed=state.completed.filter(x=>x!==el.dataset.task);if(el.checked)state.completed.push(el.dataset.task);log('Passenger '+(el.checked?'completed':'reopened')+' preparation action: '+(assessment().tasks.find(t=>t.id===el.dataset.task)?.title||el.dataset.task));});const scroll=window.scrollY;render();window.scrollTo(0,scroll);}
 if(el.dataset.issued&&state.docs[el.dataset.issued]){transact(()=>{state.docs[el.dataset.issued].issuedDate=el.value;state.documentsSavedAt=null;markCaseChanged('Passenger updated the document issue date; supported date check rerun.');});render();toast('Date check refreshed. Review and resubmit any shared changes.');}
 if(el.dataset.doc){const file=el.files?.[0];if(!file)return;await attachDocument(el.dataset.doc,file,el);}

});
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action],[data-remove-doc],[data-open-case],[data-support-action],[data-preview-doc]');if(!b)return;
 if(b.dataset.previewDoc){await viewDocument(b.dataset.previewDoc);return;}
 if(b.dataset.openCase){openDemo(b.dataset.openCase);return;}
 if(b.dataset.supportAction){if(!state.submitted||!state.profile?.consent)return;if(state.needsResubmit&&b.dataset.status==='Confirmed'){toast('Wait for the passenger to resubmit changes before confirming arrangements.');return;}const note=$('#reviewNote')?.value;if(!transact(()=>{state.assistance[b.dataset.supportAction]=b.dataset.status;log('Simulated assistance update: '+supportNames[b.dataset.supportAction]+' — '+b.dataset.status);}))return;render();if($('#reviewNote')&&note!==undefined)$('#reviewNote').value=note;toast('Simulated assistance status saved.');return;}
 if(b.dataset.removeDoc){const oldKey=state.docs[b.dataset.removeDoc]?.blobKey;const removed=transact(()=>{const id=b.dataset.removeDoc;delete state.docs[id];state.documentsSavedAt=null;if(state.corrections[id])state.corrections[id].status='requested';markCaseChanged('Passenger removed a document record: '+id);});if(removed&&oldKey)AeroFiles.remove(oldKey).catch(()=>{});render();return;}
 switch(b.dataset.action){case 'new-demo':newDemo();break;case 'print':printSummary();break;
 case 'save-documents':case 'save-continue-documents':if(transact(()=>{state.documentsSavedAt=new Date().toISOString();log('Passenger saved document progress in this browser.');})){if(b.dataset.action==='save-continue-documents')location.hash='readiness';render();toast('✓ Document progress saved successfully.');}break;
 case 'submit':if(location.hash!=='#confirm'){location.hash='confirm';return;}if(!state.profile?.consent||state.draft||activeCorrections().some(r=>r.status==='requested')){toast('Complete your draft, sharing choice and requested document replacements first.');return;}if(state.submitted&&!state.needsResubmit)return;if(transact(()=>{const again=!!(state.submittedAt||state.submitted);state.submitted=true;state.needsResubmit=false;state.submittedAt=new Date().toISOString();state.review='Pending review';for(const id of state.profile.supports)if(!state.assistance[id]||state.assistance[id]==='Needs reconfirmation')state.assistance[id]='Requested';for(const r of Object.values(state.corrections))if(r.status==='responded')r.status='resubmitted';log(again?'Passenger explicitly resubmitted the updated fictional case for demo review.':'Passenger submitted the fictional case with sharing permission.');})){render();toast('✓ Case submitted successfully. Awaiting simulated review.');}break;
 case 'withdraw':if(transact(()=>{state.profile.consent=false;if(state.draft)state.draft.consent=false;state.submitted=false;state.needsResubmit=false;state.review='Not submitted';state.assistance={};log('Passenger withdrew sharing permission. Reviewer view hidden.');})){render();toast('Sharing permission withdrawn.');}break;
 case 'reset':if(confirm('Clear only the current demo? Other saved demos will remain.')){const clearedId=activeId;if(transact(()=>{state=fresh();})){AeroFiles.clearCase(clearedId).catch(()=>{});location.hash='overview';render();toast('Current demo cleared.');}}break;
 }
});

let previewObjectUrl=null,previewSequence=0,previewReturnFocus=null;
function documentPreviewButton(id){const r=state.docs[id];if(!r)return '';return `<div class="file-preview-actions"><button type="button" class="btn secondary small" data-preview-doc="${e(id)}" ${r.blobKey?'':'disabled'}>${icon('documents')}View document</button><span class="tiny muted">${r.blobKey?'Saved '+stamp(r.at)+(r.size?' · '+formatFileSize(r.size):''):'Preview unavailable for this older record. Reattach the fictional file in Documents.'}</span></div>`;}
function formatFileSize(bytes){return bytes>=1048576?(bytes/1048576).toFixed(1)+' MB':Math.max(1,Math.round(bytes/1024))+' KB';}
async function attachDocument(id,file,input){const owner=activeId,previous=state.docs[id],was=!!previous;let saved;try{if(input)input.disabled=true;toast('Saving fictional file in this browser…');saved=await AeroFiles.save(owner,id,file);if(activeId!==owner||!state.profile||state.docs[id]!==previous||!assessment().docs.some(d=>d.id===id)){await AeroFiles.remove(saved.key);toast('The case changed while saving. Select the file again in the correct case.');return;}const ok=transact(()=>{state.docs[id]={name:file.name,at:new Date().toISOString(),blobKey:saved.key,type:saved.type,size:saved.size};if(previous)state.docs[id].previousName=previous.name;state.documentsSavedAt=null;if(state.corrections[id])state.corrections[id].status='responded';markCaseChanged('Passenger '+(was?'replaced':'added')+' '+(assessment().docs.find(d=>d.id===id)?.title||id)+': '+file.name+' (file saved in this browser).');});if(!ok){await AeroFiles.remove(saved.key);return;}if(previous?.blobKey)AeroFiles.remove(previous.blobKey).catch(()=>{});render();toast('✓ Document saved successfully. Same-browser preview is available. Content not medically verified.');}catch(error){if(saved?.key)AeroFiles.remove(saved.key).catch(()=>{});toast(error?.message||'The file could not be saved. Your previous document record is unchanged.');}finally{if(input){input.disabled=false;input.value='';}}}
function closeDocumentPreview(){previewSequence++;const dialog=$('#document-preview');if(dialog?.open)dialog.close();if(previewObjectUrl){URL.revokeObjectURL(previewObjectUrl);previewObjectUrl=null;}const body=$('#document-preview-body');if(body)body.replaceChildren();}
async function viewDocument(id){const record=state.docs[id];if(!record?.blobKey){toast('Reattach this fictional file to enable preview.');return;}const reviewer=location.hash.slice(1).split('/')[0]==='airline';if(reviewer&&(!state.submitted||!state.profile?.consent)){toast('The passenger has not shared this case.');return;}const owner=activeId;closeDocumentPreview();const sequence=previewSequence;previewReturnFocus=document.activeElement;try{const blob=await AeroFiles.get(record.blobKey);if(sequence!==previewSequence||owner!==activeId)return;if(!blob){toast('This file is no longer available in this browser. Reattach it in Documents.');return;}const dialog=$('#document-preview'),body=$('#document-preview-body'),request=state.corrections[id];$('#document-preview-title').textContent=assessment().docs.find(d=>d.id===id)?.title||'Document preview';$('#document-preview-name').textContent=record.name;$('#document-preview-meta').textContent='Added '+stamp(record.at)+(record.issuedDate?' · Report issue date '+formatDate(record.issuedDate):'')+' · '+formatFileSize(blob.size);const note=$('#document-preview-request');note.textContent=request?'Reviewer request: '+request.note+' · '+correctionLabel(request.status):'No correction request for this document.';previewObjectUrl=URL.createObjectURL(blob);const link=$('#document-preview-open');link.href=previewObjectUrl;link.download=record.name;
if(blob.type==='text/plain'){const pre=document.createElement('pre');pre.textContent=await blob.slice(0,200000).text();if(sequence!==previewSequence)return;if(blob.size>200000)pre.textContent+='\n\n[Preview truncated. Download the file to read the rest.]';body.append(pre);}else if(['image/png','image/jpeg'].includes(blob.type)){const img=document.createElement('img');img.src=previewObjectUrl;img.alt='Fictional document: '+record.name;body.append(img);}else if(blob.type==='application/pdf'){const object=document.createElement('object');object.type='application/pdf';object.data=previewObjectUrl;object.setAttribute('aria-label','PDF preview: '+record.name);const fallback=document.createElement('p');fallback.textContent='If your browser cannot display the PDF here, use Download file to view it.';object.append(fallback);body.append(object);}else{closeDocumentPreview();toast('This file type cannot be previewed. Reattach a PDF, PNG, JPEG or text file.');return;}dialog.showModal();}catch{closeDocumentPreview();toast('Could not open the local file. Reattach it in Documents.');}}

$('#document-preview').addEventListener('close',()=>{closeDocumentPreview();previewReturnFocus?.focus?.();});$('#document-preview-close').addEventListener('click',closeDocumentPreview);
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});window.addEventListener('storage',ev=>{if(ev.key===KEY){try{loadCases(JSON.parse(ev.newValue));render();}catch{toast('Unable to read the updated case.');}}});render();if(resetApplied)toast('Previous demos cleared. Start a new blank journey.');
